kit:
query PredMeta_hero($slug: String!, $definitionVersion: ID) {
  hero(by: {slug: $slug}) {
    id
    availableVersions {
      id
      name
      releaseDate
      patchType
    }
    data(version: $definitionVersion) {
      displayName
      attributes {
        stat
        values
        id
      }
      mainAttributes {
        abilityPower
        attackPower
        durability
        mobility
      }
      abilities {
        key
        displayName
        icon
        cooldown
        cost
        type
        menuDescription
        simplifiedDescription
        video
        id
      }
      perks {
        aggressionTypes
        description
        displayName
        displayOrder
        icon
        name
        perk {
          id
        }
        slot
        id
      }
      id
    }
  }
}

