counters:
query PredMeta_counters($slug: String!, $versions: [ID!], $gameModes: [GameMode!], $ranks: [ID!], $roles: [Role!], $definitionVersion: ID) {
  hero(by: {slug: $slug}) {
    id
    availableVersions {
      id
      name
      releaseDate
      patchType
    }
    data(version: $definitionVersion) {
      displayName
      id
    }
    counters: matchupStatistic(filter: {versions: $versions, gameModes: $gameModes, ranks: $ranks, roles: $roles}, metric: WINRATE, order: ASC) {
      results {
        matchesPlayed
        matchupHero {
          slug
          data(version: $definitionVersion) {
            displayName
            icon
            roles
            id
          }
          id
        }
        loserate
        winrate
        firstTowerTime
        firstTowerTimeDiff
      }
      filter {
        gameModes
        ranks
        roles
        versions
      }
    }
    antiCounters: matchupStatistic(filter: {versions: $versions, gameModes: $gameModes, ranks: $ranks, roles: $roles}, metric: WINRATE, order: DESC) {
      results {
        matchesPlayed
        matchupHero {
          slug
          data(version: $definitionVersion) {
            displayName
            icon
            roles
            id
          }
          id
        }
        loserate
        winrate
        firstTowerTime
        firstTowerTimeDiff
      }
    }
    laneCounters: matchupStatistic(filter: {versions: $versions, gameModes: $gameModes, ranks: $ranks, roles: $roles}, metric: FIRST_TOWER_TIME_DIFF, order: DESC) {
      results {
        matchesPlayed
        matchupHero {
          slug
          data(version: $definitionVersion) {
            displayName
            icon
            roles
            id
          }
          id
        }
        loserate
        winrate
        firstTowerTime
        firstTowerTimeDiff
      }
    }
  }
}

